        with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent":"CubeDynamics-public-acceptance/1.0"}),timeout=30) as response:
            payload=json.load(response); item={"url":url,"status":response.status}
        if isinstance(payload,list): item["releases"]=[{"tag_name":r["tag_name"],"name":r["name"],"prerelease":r["prerelease"],"assets":[{"name":a["name"],"url":a["browser_download_url"]} for a in r["assets"]]} for r in payload]
        else: item["package_name"]=payload["info"]["name"]; item["version"]=payload["info"]["version"]
    except urllib.error.HTTPError as error: item={"url":url,"status":error.code,"error":str(error)}
    records.append(item)
